import React, { useState } from 'react';
import Layout from '../components/Layout';
import { User, Mail, Lock } from 'lucide-react';

const SignInPage = ({ onSignIn, onNavigate }) => {
  const [form, setForm] = useState({
    name: '',
    email: '',
    password: '',
    confirm: '',
  });
  const [error, setError] = useState('');

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (form.password !== form.confirm) {
      setError('كلمات المرور غير متطابقة');
      return;
    }
    await onSignIn(form);
  };

  return (
    <Layout onNavigate={onNavigate}>
      <div className="flex justify-center items-center py-20 px-4">
        <form className="bg-white p-8 rounded-xl shadow-lg w-full max-w-md">
          <h2 className="text-3xl font-bold text-[#0c1f40] mb-6 text-center">
            إنشاء حساب
          </h2>

          {error && <p className="text-red-600 mb-4">{error}</p>}

          <input
            placeholder="الاسم"
            className="w-full border p-3 rounded mb-4"
            onChange={(e) => setForm({ ...form, name: e.target.value })}
          />

          <input
            placeholder="البريد الإلكتروني"
            className="w-full border p-3 rounded mb-4"
            onChange={(e) => setForm({ ...form, email: e.target.value })}
          />

          <input
            type="password"
            placeholder="كلمة المرور"
            className="w-full border p-3 rounded mb-4"
            onChange={(e) => setForm({ ...form, password: e.target.value })}
          />

          <input
            type="password"
            placeholder="تأكيد كلمة المرور"
            className="w-full border p-3 rounded mb-6"
            onChange={(e) => setForm({ ...form, confirm: e.target.value })}
          />

          <button className="w-full bg-[#0c1f40] text-white py-3 rounded font-bold">
            تسجيل
          </button>
        </form>
      </div>
    </Layout>
  );
};

export default SignInPage;
